import{_ as o,c as t,a2 as e,o as n}from"./chunks/framework.BQmytedh.js";const y=JSON.parse('{"title":"《如果》","description":"","frontmatter":{},"headers":[],"relativePath":"哲思_人文_社科/箴言/长文/如果-拉迪亚德·吉卜林.md","filePath":"哲思_人文_社科/箴言/长文/如果-拉迪亚德·吉卜林.md","lastUpdated":1733761377000}'),a={name:"哲思_人文_社科/箴言/长文/如果-拉迪亚德·吉卜林.md"};function r(i,p,s,u,d,h){return n(),t("div",null,p[0]||(p[0]=[e('<h1 id="《如果》" tabindex="-1">《如果》 <a class="header-anchor" href="#《如果》" aria-label="Permalink to &quot;《如果》&quot;">​</a></h1><p>拉迪亚德·吉卜林</p><p>If——</p><p>By Rudyard Kipling</p><p>译 黄福海</p><p>如果你能冷静，即便周围的所有人</p><p>都已丧失理智，并把责任推卸给你；</p><p>If you can keep your head when all about you</p><p>Are losing theirs and blaming it on you;</p><p>如果你能自信，即便周围的所有人</p><p>都怀疑你，而你对此也不心存芥蒂；</p><p>If you can trust yourself when all men doubt you,</p><p>But make allowance for their doubting too;</p><p>如果你能等待，而不为此失去耐性，</p><p>或者面对谎言诬蔑，不以谎言反击，</p><p>或者被人忌恨，不让仇恨占据心灵，</p><p>不高谈阔论，也不表现得忘乎所以；</p><p>If you can wait and not be tired by waiting,</p><p>Or being lied about, don’t deal in lies,</p><p>Or being hated don’t give way to hating,</p><p>And yet don’t look too good, nor talk too wise;</p><p>如果你有梦想，但又不被梦想支配；</p><p>If you can dream—and not make dreams your master;</p><p>如果你能思考，又不以思想家自居；</p><p>If you can think—and not make thoughts your aim;</p><p>如果你能将胜利与灾难同等看待，</p><p>并把它们看成是两种虚妄的骗局；</p><p>If you can meet with Triumph and Disaster</p><p>And treat those two impostors just the same;</p><p>如果你能忍耐，听着你所说的真理</p><p>被无赖们歪曲利用，再将傻子蒙骗；</p><p>或者眼看你倾注心血的事业毁弃，</p><p>你能俯身，用破旧的工具重新修建；</p><p>If you can bear to hear the truth you’ve spoken</p><p>Twisted by knaves to make a trap for fools,</p><p>Or watch the things you gave your life to, broken,</p><p>And stoop and build’ em up with worn out tools;</p><p>如果你能把收获都堆成一座小塔，</p><p>孤注一掷，把它交给一次冒险行动，</p><p>即使失败，你也能再次从起点出发，</p><p>而绝口不谈你曾经遭受过的伤痛；</p><p>If you can make one heap of all your winnings</p><p>And risk it on one turn of pitch and toss</p><p>And lose, and start again at your beginnings</p><p>And never breathe a word about your loss;</p><p>如果你能迫使你的心、神经和筋骨</p><p>在你身心困乏，甚至精疲力竭之时</p><p>还能够挺住，依然为你的行动服务，</p><p>只要意志还在对你的身体说：“坚持！”</p><p>If you can force your heart and nerve and sinew</p><p>To serve your turn long after they are gone,</p><p>And so hold on when there is nothing in you</p><p>Except the Will which says to them: “Hold on!”</p><p>如果你与平民交谈，能以真诚为怀，</p><p>或者跟国王同行，而又不失平常心；</p><p>If you can talk with crowds and keep your virtue,</p><p>Or walk with Kings—nor lose the common touch;</p><p>如果敌人和挚友都无法将你伤害，</p><p>如果所有人都敬重你，但不失分寸；</p><p>If neither foes nor loving friends can hurt you;</p><p>If all men count with you, but none too much;</p><p>如果你对于不近情理的每一分钟，</p><p>都能跑出具有六十秒价值的路程；</p><p>那么世界就是你的，一切归你掌控，</p><p>而你，我的孩子，你将成为真正的人！</p><p>If you can fill the unforgiving minute</p><p>With sixty seconds’ worth of distance run——</p><p>Yours is the Earth and everything that’s in it,</p><p>And—which is more—you’ll be a Man, my son!</p>',69)]))}const c=o(a,[["render",r]]);export{y as __pageData,c as default};
